import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests unitarios de GameService.
 */
public class GameServiceTest {

    private GameService gameService;
    private Player player1;
    private Player player2;

    @BeforeEach
    void setUp() {
        gameService = new GameServiceImpl();
        player1 = new Player("p1", "Alice");
        player2 = new Player("p2", "Bob");
    }

    @Test
    void testCreateGame() {
        Game game = gameService.createGame("Inazuma Match", player1);

        assertNotNull(game);
        assertEquals("Inazuma Match", game.getName());
        assertEquals(GameState.WAITING, game.getState());
        assertEquals(1, game.getPlayers().size());
        assertEquals(player1, game.getPlayers().get(0));
    }

    @Test
    void testJoinGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        game = gameService.joinGame(game.getId(), player2);

        assertEquals(2, game.getPlayers().size());
        assertEquals(player2, game.getPlayers().get(1));
        assertEquals(GameState.WAITING, game.getState());
    }

    @Test
    void testJoinGameCannotAddThirdPlayer() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);

        Player player3 = new Player("p3", "Charlie");
        assertThrows(IllegalStateException.class, () -> gameService.joinGame(game.getId(), player3));
    }

    @Test
    void testStartGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);

        game = gameService.startGame(game.getId());

        assertEquals(GameState.IN_PROGRESS, game.getState());
        assertEquals(0, game.getCurrentPlayerIndex());
    }

    @Test
    void testStartGameRequiresTwoPlayers() {
        Game game = gameService.createGame("Inazuma Match", player1);

        assertThrows(IllegalStateException.class, () -> gameService.startGame(game.getId()));
    }

    @Test
    void testNextTurn() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        game = gameService.startGame(game.getId());

        assertEquals(0, game.getCurrentPlayerIndex());
        assertEquals(0, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(1, game.getCurrentPlayerIndex());
        assertEquals(1, game.getTurnCount());

        game = gameService.nextTurn(game.getId());

        assertEquals(0, game.getCurrentPlayerIndex());
        assertEquals(2, game.getTurnCount());
    }

    @Test
    void testExecuteMoveValidatesPlayerTurn() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        final Game startedGame = gameService.startGame(game.getId());

        // Intenta mover con player2 pero es turno de player1
        Move move = new Move(player2.getId(), 0, 0);
        assertThrows(PlayerNotInTurnException.class, 
            () -> gameService.executeMove(startedGame.getId(), player2.getId(), move));
    }

    @Test
    void testExecuteMoveValidatesPlayerAlive() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        final Game startedGame = gameService.startGame(game.getId());

        // Marca player1 como muerto
        startedGame.getCurrentPlayer().setAlive(false);

        Move move = new Move(player1.getId(), 0, 0);
        assertThrows(InvalidMoveException.class, 
            () -> gameService.executeMove(startedGame.getId(), player1.getId(), move));
    }

    @Test
    void testFinishGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        gameService.startGame(game.getId());

        game = gameService.finishGame(game.getId(), player1.getId());

        assertEquals(GameState.FINISHED, game.getState());
        assertEquals(player1.getId(), game.getWinnerPlayerId());
        assertNotNull(game.getFinishedAt());
    }

    @Test
    void testAbandonGame() {
        Game game = gameService.createGame("Inazuma Match", player1);
        gameService.joinGame(game.getId(), player2);
        gameService.startGame(game.getId());

        game = gameService.abandonGame(game.getId());

        assertEquals(GameState.ABANDONED, game.getState());
        assertNotNull(game.getFinishedAt());
    }

    @Test
    void testGetGameReturnsNull() {
        assertNull(gameService.getGame("nonexistent"));
    }
}

package es.iesquevedo.service.impl;

import es.iesquevedo.model.Game;
import es.iesquevedo.model.GameState;
import es.iesquevedo.model.Move;
import es.iesquevedo.model.Player;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

class GameServiceImplExecuteMoveTest {

    private GameServiceImpl gameService;
    private Game game;
    private Player player1;
    private Player player2;

    @BeforeEach
    void setUp() {
        gameService = new GameServiceImpl();
        player1 = new Player("p1", "Negro");
        player2 = new Player("p2", "Blanco");

        game = gameService.createGame("testGame", player1);
        gameService.joinGame(game.getId(), player2);
        game = gameService.startGame(game.getId());
    }

    @Test
    void testPlaceStoneChangesBoard() {
        Move move = new Move("p1", 0, 0);
        Game result = gameService.executeMove(game.getId(), "p1", move);

        assertEquals(1, result.getBoard().getCell(0, 0)); // Negro (1) en (0,0)
        assertEquals(1, result.getMoves().size());
        assertEquals(1, result.getCurrentPlayerIndex()); // Cambió a Blanco
    }

    @Test
    void testDoublPassEndsGame() {
        // Negro pasa
        Move pass1 = new Move("p1", true);
        game = gameService.executeMove(game.getId(), "p1", pass1);
        assertEquals(1, game.getConsecutivePasses());
        assertEquals(GameState.IN_PROGRESS, game.getState());

        // Blanco pasa
        Move pass2 = new Move("p2", true);
        game = gameService.executeMove(game.getId(), "p2", pass2);
        assertEquals(GameState.FINISHED, game.getState());
        assertNotNull(game.getWinnerPlayerId());
    }

    @Test
    void testCaptureRemovesPieces() {
        // Crear una situación de captura correcta:
        // Rodear una piedra blanca solitaria en (3,3) con piedras negras
        // N en (2,3)
        Move m1 = new Move("p1", 2, 3);
        game = gameService.executeMove(game.getId(), "p1", m1);

        // B en (3,3) - la piedra que será capturada
        Move m2 = new Move("p2", 3, 3);
        game = gameService.executeMove(game.getId(), "p2", m2);

        // N en (4,3)
        Move m3 = new Move("p1", 4, 3);
        game = gameService.executeMove(game.getId(), "p1", m3);

        // B pasa
        Move m4 = new Move("p2", true);
        game = gameService.executeMove(game.getId(), "p2", m4);

        // N en (3,2)
        Move m5 = new Move("p1", 3, 2);
        game = gameService.executeMove(game.getId(), "p1", m5);

        // B pasa
        Move m6 = new Move("p2", true);
        game = gameService.executeMove(game.getId(), "p2", m6);

        // N en (3,4) y captura la piedra blanca en (3,3)
        Move m7 = new Move("p1", 3, 4);
        game = gameService.executeMove(game.getId(), "p1", m7);

        // Verificar que la piedra blanca fue capturada
        assertEquals(0, game.getBoard().getCell(3, 3), 
            "La piedra blanca en (3,3) debe estar capturada (rodeada por Negro)");
    }

    @Test
    void testConsecutivePassesResetAfterMove() {
        // Negro pasa
        Move pass1 = new Move("p1", true);
        game = gameService.executeMove(game.getId(), "p1", pass1);
        assertEquals(1, game.getConsecutivePasses());

        // Blanco juega (no pasa)
        Move move = new Move("p2", 0, 0);
        game = gameService.executeMove(game.getId(), "p2", move);
        assertEquals(0, game.getConsecutivePasses(), "Los pases consecutivos deben resetear con un movimiento");
    }

    @Test
    void testMoveRecordedInHistory() {
        Move move1 = new Move("p1", 0, 0);
        game = gameService.executeMove(game.getId(), "p1", move1);
        assertEquals(1, game.getMoves().size());

        Move move2 = new Move("p2", 1, 1);
        game = gameService.executeMove(game.getId(), "p2", move2);
        assertEquals(2, game.getMoves().size());
    }

    @Test
    void testTurnAlternatesCorrectly() {
        assertEquals(0, game.getCurrentPlayerIndex(), "Debe empezar con Negro (índice 0)");

        Move move1 = new Move("p1", 0, 0);
        game = gameService.executeMove(game.getId(), "p1", move1);
        assertEquals(1, game.getCurrentPlayerIndex(), "Debe cambiar a Blanco (índice 1)");

        Move move2 = new Move("p2", 1, 1);
        game = gameService.executeMove(game.getId(), "p2", move2);
        assertEquals(0, game.getCurrentPlayerIndex(), "Debe cambiar a Negro (índice 0)");
    }

    @Test
    void testPassDoesNotPlaceStone() {
        Move pass = new Move("p1", true);
        game = gameService.executeMove(game.getId(), "p1", pass);

        // El tablero debe seguir vacío
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                assertEquals(0, game.getBoard().getCell(r, c), "Tablero debe estar vacío después de pase");
            }
        }
    }
}

package es.iesquevedo.service.impl;

import es.iesquevedo.exception.InvalidMoveException;
import es.iesquevedo.exception.PlayerNotInTurnException;
import es.iesquevedo.model.Board;
import es.iesquevedo.model.Game;
import es.iesquevedo.model.GameState;
import es.iesquevedo.model.Move;
import es.iesquevedo.model.Player;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertThrows;

class InazumaGoMoveValidatorTest {

    private InazumaGoMoveValidator validator;
    private Game game;
    private Player player1;
    private Player player2;

    @BeforeEach
    void setUp() {
        validator = new InazumaGoMoveValidator();
        player1 = new Player("p1", "Negro");
        player2 = new Player("p2", "Blanco");
        game = new Game("test", player1);
        game.addPlayer(player2);
        game.start();
    }

    @Test
    void testValidPlyacementMove() {
        Move move = new Move("p1", 0, 0);
        assertDoesNotThrow(() -> validator.validateMove(game, move));
    }

    @Test
    void testValidPassMove() {
        Move move = new Move("p1", true);
        assertDoesNotThrow(() -> validator.validateMove(game, move));
    }

    @Test
    void testNotPlayerTurnThrows() {
        Move move = new Move("p2", 0, 0); // Blanco intenta jugar pero es turno de Negro
        assertThrows(PlayerNotInTurnException.class, () -> validator.validateMove(game, move));
    }

    @Test
    void testGameNotInProgressThrows() {
        game.setState(GameState.FINISHED);
        Move move = new Move("p1", 0, 0);
        assertThrows(InvalidMoveException.class, () -> validator.validateMove(game, move));
    }

    @Test
    void testPositionOutOfBoundsThrows() {
        Move move = new Move("p1", 9, 0); // Fuera del tablero 9x9
        assertThrows(InvalidMoveException.class, () -> validator.validateMove(game, move));

        Move move2 = new Move("p1", -1, 5);
        assertThrows(InvalidMoveException.class, () -> validator.validateMove(game, move2));
    }

    @Test
    void testOccupiedPositionThrows() {
        Board board = game.getBoard();
        board.placeStone(0, 0, 1); // Colocar piedra negra

        Move move = new Move("p1", 0, 0);
        assertThrows(InvalidMoveException.class, () -> validator.validateMove(game, move));
    }

    @Test
    void testSuicideMoveThrows() {
        // Crear una situación de suicidio: piedra rodeada sin libertades
        Board board = game.getBoard();
        // Rodear posición (2,2) de manera que no haya libertades
        board.placeStone(1, 2, 2); // Blanco arriba
        board.placeStone(3, 2, 2); // Blanco abajo
        board.placeStone(2, 1, 2); // Blanco izquierda
        board.placeStone(2, 3, 2); // Blanco derecha

        Move move = new Move("p1", 2, 2); // Negro intenta colocar en centro rodeado
        assertThrows(InvalidMoveException.class, () -> validator.validateMove(game, move));
    }

    @Test
    void testCaptureMovesAllowed() {
        // Crear situación donde Negro captura: piedra blanca rodeada
        Board board = game.getBoard();
        board.placeStone(0, 1, 2); // Blanco en (0,1)
        board.placeStone(1, 0, 1); // Negro en (1,0)
        board.placeStone(1, 2, 1); // Negro en (1,2)
        board.placeStone(2, 1, 1); // Negro en (2,1)

        // Negro coloca en (0,0) capturando a Blanco
        Move move = new Move("p1", 0, 0);
        assertDoesNotThrow(() -> validator.validateMove(game, move));
    }

    @Test
    void testSecondPlayerTurnAfterFirst() {
        game.nextTurn(); // Cambiar a turno de Blanco

        Move move = new Move("p2", 1, 1);
        assertDoesNotThrow(() -> validator.validateMove(game, move));
    }
}
